/**
 * ImportVDPDoctors
 * 
 * Snippet per importare i medici del Villa dei Pini
 */

if (!isset($modx) || !is_object($modx)) {
    return 'Error: MODX not available';
}

// Funzione helper per importare un singolo medico
function importDoctor($modx, $doctorData, $struttura_id, $struttura_title) {
    try {
        // Verifichiamo che i dati richiesti siano presenti
        if (empty($doctorData['pagetitle']) || empty($doctorData['alias']) || empty($doctorData['content'])) {
            throw new Exception("Missing required data for doctor");
        }

        $doc = $modx->newObject('modResource');
        if (!$doc) {
            throw new Exception("Failed to create new resource");
        }

        $timestamp = time();
        
        // Aggiungiamo il link dinamico alla struttura alla fine del contenuto
        $content = $doctorData['content'];
        // Modifica del pattern regex per essere più specifico
        $content = preg_replace(
            '/<h2>Struttura<\/h2>\s*<p>Villa dei Pini<\/p>/',
            "<h2>Struttura</h2><p><a href=\"[[~{$struttura_id}]]\" title=\"{$struttura_title}\">{$struttura_title}</a></p>",
            $content
        );
        
        $doc->fromArray([
            "pagetitle" => $doctorData['pagetitle'],
            "alias" => $doctorData['alias'],
            "content" => $content,
            "parent" => 280,
            "template" => 8,
            "published" => 1,
            "context_key" => "web",
            "richtext" => 1,
            "createdon" => $timestamp,
            "createdby" => 1,
            "editedon" => $timestamp,
            "editedby" => 1,
            "publishedon" => $timestamp,
            "publishedby" => 1
        ]);

        if (!$doc->save()) {
            throw new Exception("Failed to save: {$doctorData['pagetitle']}");
        }

        // Verifichiamo che il TV esista prima di crearlo
        $tv = $modx->getObject('modTemplateVar', ['id' => 28]);
        if (!$tv) {
            throw new Exception("Template Variable ID 28 not found");
        }

        // Create TV value
        $tvr = $modx->newObject("modTemplateVarResource");
        $tvr->set("tmplvarid", 28);
        $tvr->set("contentid", $doc->get("id"));
        $tvr->set("value", $struttura_id);
        
        if (!$tvr->save()) {
            throw new Exception("TV save failed: {$doctorData['pagetitle']}");
        }

        return ["success" => true, "message" => "Imported: {$doctorData['pagetitle']}"];
    } catch (Exception $e) {
        return ["success" => false, "message" => $e->getMessage()];
    }
}

